import{K as i,a as r,c,b as t,k as l,q as f,ac as s}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"Office 版本选择、安装与工作环境","description":"分清 Microsoft 365、Office 买断版、网页版与 Mac 版，完成安装、账号检查、界面设置、更新与首次保存。","frontmatter":{"title":"Office 版本选择、安装与工作环境","description":"分清 Microsoft 365、Office 买断版、网页版与 Mac 版，完成安装、账号检查、界面设置、更新与首次保存。","showdocs":{"topics":[{"id":"office","title":"Office","link":"/topics/office/"}],"kind":"使用指南","scope":"general","audience":"general","group":"工程与工具","seriesTitle":"Office · 入门与通用操作","summary":"分清 Microsoft 365、Office 买断版、网页版与 Mac 版，完成安装、账号检查、界面设置、更新与首次保存。","status":"active","related":[{"title":"Excel 实战：建立可刷新、可核对的月报","link":"/tools/office/excel/project","kind":"实践案例","scope":"general","audience":"general"},{"title":"Office 常见问题排查与交付检查表","link":"/tools/office/collaboration/troubleshooting","kind":"故障排查","scope":"general","audience":"general"},{"title":"Office 常用快捷键、选择与粘贴技巧","link":"/tools/office/start/shortcuts","kind":"参考资料","scope":"general","audience":"general"},{"title":"Office 综合实战：从数据到报告、演示和会议","link":"/tools/office/collaboration/workflow","kind":"实践案例","scope":"general","audience":"general"},{"title":"Word 实战：制作可维护的项目报告","link":"/tools/office/word/report","kind":"实践案例","scope":"general","audience":"general"}],"prev":{"text":"Office 学习路线与办公场景","link":"/tools/office/start/overview"},"next":{"text":"Office 文件保存、格式转换与版本恢复","link":"/tools/office/start/files"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Office 学习路线与办公场景","link":"/tools/office/start/overview"},"next":{"text":"Office 文件保存、格式转换与版本恢复","link":"/tools/office/start/files"}},"headers":[],"relativePath":"tools/office/start/setup.md","filePath":"tools/office/start/setup.md"}'),n={name:"tools/office/start/setup.md"},k=Object.assign(n,{setup(d){const o={path:"/tools/office/start/setup",app:"Word",title:"第一次打开 Office 后检查环境",steps:[{tab:"文件",command:"账户",setting:"产品信息；登录身份",anchor:"walkthrough-1"},{tab:"文件",command:"新建",setting:"空白文档；输入：Office 首次练习",anchor:"walkthrough-2"},{tab:"视图",command:"打印布局",setting:"显示功能区；缩放：适合阅读",anchor:"walkthrough-3"}]};return(h,e)=>{const a=i("OfficeGuide");return r(),c("div",null,[e[0]||(e[0]=t("h1",{id:"office-版本选择、安装与工作环境",tabindex:"-1"},[l("Office 版本选择、安装与工作环境 "),t("a",{class:"header-anchor",href:"#office-版本选择、安装与工作环境","aria-label":'Permalink to "Office 版本选择、安装与工作环境"'},"​")],-1)),e[1]||(e[1]=t("p",null,"开始之前先确认自己需要哪些应用、在哪种系统使用、文件由谁管理。Office 套件、Microsoft 365 订阅和公司分配的许可证并不完全相同，不能只凭桌面上有 Word 图标判断全部功能都可用。",-1)),f(a,{guide:o}),e[2]||(e[2]=s('<h2 id="identify" tabindex="-1">确认产品和账号 <a class="header-anchor" href="#identify" aria-label="Permalink to &quot;确认产品和账号 {#identify}&quot;">​</a></h2><p>Windows 桌面版通常可在“文件 → 账户”查看产品名称、登录账号、激活状态和更新入口；“关于 Word / Excel”可查看版本、内部版本号和位数。把这些信息记录下来，排错时比“我用的是新版”更有用。</p><table tabindex="0"><thead><tr><th>类型</th><th>使用时需要确认</th></tr></thead><tbody><tr><td>Microsoft 365 订阅</td><td>订阅是否包含桌面应用，分配给哪个账号，组织是否限制功能</td></tr><tr><td>Office 2021 / 2024 等一次性购买版</td><td>所购版本具体包含哪些应用；不要假设持续获得订阅新功能</td></tr><tr><td>网页版</td><td>浏览器和网络、云端文件位置、缺少的桌面功能</td></tr><tr><td>Mac 桌面版</td><td>菜单和快捷键差异，以及数据分析、加载项支持情况</td></tr><tr><td>移动端</td><td>适合阅读和轻量修改，复杂排版交付仍需在目标环境检查</td></tr></tbody></table><p>Access 是 Windows 桌面应用；购买的套件不一定包含它。Visio、Project 等也不能因为名称接近 Office 就视作默认包含。本专题的基础操作不依赖 Copilot；AI 功能的账号权限和生成内容需要另外确认。</p><h2 id="install" tabindex="-1">安装与首次启动 <a class="header-anchor" href="#install" aria-label="Permalink to &quot;安装与首次启动 {#install}&quot;">​</a></h2><ol><li>从公司软件门户、组织提供的安装入口或微软账号对应的官方服务页面获取安装程序。</li><li>确认系统支持情况、磁盘空间、安装语言；公司电脑先沿用组织的部署方式。</li><li>如果已有 Office，先查版本和加载项需求。需要更换位数时，检查旧版插件、宏和数据库驱动的兼容性，再按官方流程处理原安装。</li><li>安装完成后启动 Word，用拥有授权的账号登录。个人账号与工作/学校账号可能使用相同邮箱文字，却对应不同身份体系。</li><li>新建空白文档，输入两行文字，保存为 <code>.docx</code>，关闭再打开。能编辑、保存并重新打开，才完成最基本的环境检查。</li></ol><p>安装失败时记下错误代码、时间和产品版本。不要为解决激活失败安装来路不明的工具；优先核对账号、许可证分配、网络和系统时间。</p><h2 id="workspace" tabindex="-1">调整常用界面 <a class="header-anchor" href="#workspace" aria-label="Permalink to &quot;调整常用界面 {#workspace}&quot;">​</a></h2><p>功能区由“开始、插入、布局、审阅、视图”等选项卡组成。选中表格、图片或图表时，会出现对应的上下文选项卡；没有选中对象时看不到这些菜单是正常现象。</p><p>常用设置可按以下顺序调整：在“文件 → 选项”检查保存位置和语言；在“自定义快速访问工具栏”添加自己常用的保存、撤销、打印预览；在“视图”中打开需要的标尺或导航窗格。不要一次隐藏大量按钮，否则之后无法判断教程中的功能去哪了。</p><p>Word 的显示比例只改变屏幕阅读大小，不改变打印字号。Excel 的显示网格线和打印网格线是不同设置。PowerPoint 的编辑比例不决定幻灯片尺寸。这三点最容易在“看着合适，输出却不对”时被混淆。</p><h2 id="compatibility" tabindex="-1">更新、插件与兼容 <a class="header-anchor" href="#compatibility" aria-label="Permalink to &quot;更新、插件与兼容 {#compatibility}&quot;">​</a></h2><p>组织管理的 Office 可能没有可自行点击的更新按钮，或更新由管理员按通道推送。重要交付前先在副本上检查新版本，不临时升级后才发现字体或加载项变化。</p><p>旧格式 <code>.doc</code>、<code>.xls</code>、<code>.ppt</code> 可能进入兼容模式。需要新功能时先另存为当前格式，再检查布局、公式和对象；涉及宏的文件要使用支持宏的格式，不能把扩展名直接改掉当作转换。字体缺失、外部链接失效和第三方插件异常，都可能导致同一文件在两台电脑上表现不同。</p><h2 id="practice" tabindex="-1">练习与验收 <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;练习与验收 {#practice}&quot;">​</a></h2><p>分别建立 <code>练习文档.docx</code>、<code>练习表格.xlsx</code> 和 <code>练习演示.pptx</code>，放在同一个练习文件夹。完成保存、关闭、重新打开，并找到每个文件的实际路径。记录应用版本、系统和账号类型，确认“另存为”和“导出 PDF”在哪里。</p><p>如果某应用缺失，先核对授权包含范围；如果只能只读，检查激活、文件权限和受保护视图；如果仅某个文件打不开，用新建空白文件区分安装问题与文件问题。</p><p>进一步查询：<a href="https://support.microsoft.com/en-us/microsoft-365" target="_blank" rel="noopener noreferrer">Microsoft 365 帮助</a>、<a href="https://learn.microsoft.com/en-us/office/dev/scripts/testing/platform-limits" target="_blank" rel="noopener noreferrer">Office Scripts 的平台和许可要求</a>。后者用于高级自动化功能的资格检查，不能代替基础 Office 许可证判断。</p><h2 id="walkthrough" tabindex="-1">图示跟做：第一次打开 Office 后检查环境 <a class="header-anchor" href="#walkthrough" aria-label="Permalink to &quot;图示跟做：第一次打开 Office 后检查环境 {#walkthrough}&quot;">​</a></h2><p>按上方图示切换三个关键步骤；下面保留完整操作和检查结果，便于跟做与回查。请先使用练习副本。</p><h3 id="walkthrough-1" tabindex="-1">第 1 步：确认正在用哪个产品 <a class="header-anchor" href="#walkthrough-1" aria-label="Permalink to &quot;第 1 步：确认正在用哪个产品 {#walkthrough-1}&quot;">​</a></h3><p><strong>定位：文件 → 账户。</strong></p><p>在 Word 中打开“文件 → 账户”（部分版本显示 Office 账户），记录产品名称、激活状态和登录账号所属组织。购买许可的账号与编辑云端文件的账号可能不同；发现不一致时先确认授权归属，不要重复购买。公司设备缺少安装权限时，按组织的软件安装流程处理。</p><h3 id="walkthrough-2" tabindex="-1">第 2 步：验证最小编辑闭环 <a class="header-anchor" href="#walkthrough-2" aria-label="Permalink to &quot;第 2 步：验证最小编辑闭环 {#walkthrough-2}&quot;">​</a></h3><p><strong>定位：文件 → 新建。</strong></p><p>新建空白文档，输入一行“Office 首次练习”，用“文件 → 另存为”保存到自己能找到的文件夹。关闭文档后从该文件夹重新打开，确认内容仍在。这个测试能区分应用无法编辑、文件夹无写入权限、只是找错文件位置等情况。</p><h3 id="walkthrough-3" tabindex="-1">第 3 步：认识功能区与上下文菜单 <a class="header-anchor" href="#walkthrough-3" aria-label="Permalink to &quot;第 3 步：认识功能区与上下文菜单 {#walkthrough-3}&quot;">​</a></h3><p><strong>定位：视图 → 打印布局。</strong></p><p>切换到打印布局，试着选中文字、图片或表格，观察顶部出现的选项卡。按钮只在选中相应对象后出现时，并不代表安装缺失。搜索框输入“页边距”，核对结果打开的是页面设置；以后找不到命令时先用功能名称搜索。</p><h3 id="walkthrough-check" tabindex="-1">没有得到预期结果时 <a class="header-anchor" href="#walkthrough-check" aria-label="Permalink to &quot;没有得到预期结果时 {#walkthrough-check}&quot;">​</a></h3><p>Mac 的账号与偏好设置入口、网页版的菜单与桌面版不同。先记录产品和平台，再对照官方帮助；不要把“找不到按钮”直接当成需要重装。</p>',31))])}}});export{u as __pageData,k as default};
